export type JsonSchema =
  | boolean
  | {
      [key: string]: unknown;
      type?: string | string[];
      properties?: Record<string, JsonSchema>;
      required?: string[];
      enum?: unknown[];
      description?: string;
      title?: string;
      items?: JsonSchema;
    };
export interface ToolDefinition {
  name: string;
  title?: string;
  description?: string;
  inputSchema: JsonSchema;
  annotations?: {
    readOnlyHint?: boolean;
    destructiveHint?: boolean;
    untrustedContentHint?: boolean;
    consequentialHint?: boolean;
    [key: string]: unknown;
  };
}
export interface Execution {
  id: string;
  name: string;
  source: "human" | "agent" | "simulator";
  status: "running" | "success" | "error" | "cancelled";
  startedAt: number;
  completedAt?: number;
  args: Record<string, unknown>;
  result?: unknown;
  error?: string;
  progress?: { progress: number; total?: number; message?: string };
}
export type Support = "checking" | "native" | "legacy" | "unsupported";
export interface ToolContext {
  signal: AbortSignal;
  source: Execution["source"];
}
export interface WebTool extends ToolDefinition {
  execute: (
    args: Record<string, unknown>,
    context: ToolContext,
  ) => unknown | Promise<unknown>;
}
export function errorMessage(error: unknown) {
  return error instanceof Error ? error.message : "The operation failed.";
}

import Ajv2020 from "ajv/dist/2020.js";
import addFormats from "ajv-formats";
import type { JsonSchema } from "@/lib/mcp/types";
const ajv = new Ajv2020({
  allErrors: true,
  strict: false,
  validateFormats: true,
  validateSchema: true,
});
addFormats(ajv);
export function validateArguments(
  schema: JsonSchema,
  value: unknown,
): string | null {
  try {
    const validate = ajv.compile(schema);
    if (validate(value)) return null;
    return (validate.errors ?? [])
      .map((e) => `${e.instancePath || "Input"} ${e.message}`)
      .join("; ");
  } catch {
    return "This schema cannot be validated locally. Provide a self-contained JSON Schema 2020-12 without external references.";
  }
}
export function simpleFields(
  schema: JsonSchema,
): schema is Exclude<JsonSchema, boolean> {
  if (
    !schema ||
    typeof schema !== "object" ||
    Array.isArray(schema) ||
    schema.type !== "object"
  )
    return false;
  if (
    schema.properties &&
    (typeof schema.properties !== "object" || Array.isArray(schema.properties))
  )
    return false;
  if (
    Object.keys(schema).some((k) =>
      [
        "$ref",
        "allOf",
        "anyOf",
        "oneOf",
        "if",
        "dependentSchemas",
        "patternProperties",
      ].includes(k),
    )
  )
    return false;
  return Object.values(schema.properties ?? {}).every(
    (p) =>
      p !== null &&
      typeof p === "object" &&
      !Array.isArray(p) &&
      ["string", "number", "integer", "boolean"].includes(String(p.type)) &&
      !p.$ref &&
      !p.anyOf &&
      !p.oneOf &&
      !p.allOf,
  );
}

import {
  errorMessage,
  type Execution,
  type Support,
  type WebTool,
} from "@/lib/mcp/types";
import { validateArguments } from "@/lib/mcp/schema";
export interface NativeContext {
  registerTool(
    tool: object,
    options?: { signal: AbortSignal },
  ): void | Promise<void>;
  unregisterTool?: (name: string) => void;
}
export function detectWebMCP(): { support: Support; context?: NativeContext } {
  if (typeof document === "undefined") return { support: "checking" };
  const modern = (document as Document & { modelContext?: NativeContext })
    .modelContext;
  if (modern?.registerTool) return { support: "native", context: modern };
  const legacy = (navigator as Navigator & { modelContext?: NativeContext })
    .modelContext;
  return legacy?.registerTool
    ? { support: "legacy", context: legacy }
    : { support: "unsupported" };
}
export class WebMCPStore {
  private tools = new Map<string, WebTool>();
  private listeners = new Set<() => void>();
  private active = new Map<string, AbortController>();
  private snapshot: {
    tools: WebTool[];
    executions: Execution[];
    support: Support;
    error?: string;
  } = { tools: [], executions: [], support: "checking" };
  subscribe = (callback: () => void) => {
    this.listeners.add(callback);
    return () => {
      this.listeners.delete(callback);
    };
  };
  getSnapshot = () => this.snapshot;
  private emit(patch: Partial<typeof this.snapshot>) {
    this.snapshot = { ...this.snapshot, ...patch };
    this.listeners.forEach((fn) => fn());
  }
  detect() {
    this.emit({ support: detectWebMCP().support });
  }
  register(tool: WebTool) {
    if (this.tools.has(tool.name))
      throw new Error(`Duplicate WebMCP tool: ${tool.name}`);
    this.tools.set(tool.name, tool);
    this.emit({ tools: [...this.tools.values()] });
    const lifecycle = new AbortController();
    const { context, support } = detectWebMCP();
    const exposed = {
      name: tool.name,
      title: tool.title,
      description: tool.description ?? tool.name,
      inputSchema: tool.inputSchema,
      annotations: {
        readOnlyHint: tool.annotations?.readOnlyHint,
        untrustedContentHint: tool.annotations?.untrustedContentHint,
        consequentialHint: tool.annotations?.consequentialHint,
      },
      execute: (
        args: Record<string, unknown>,
        options?: { signal?: AbortSignal },
      ) => this.run(tool.name, args, "agent", options?.signal),
    };
    try {
      Promise.resolve(
        context?.registerTool(exposed, { signal: lifecycle.signal }),
      ).catch((error) => {
        if (!lifecycle.signal.aborted)
          this.emit({ error: errorMessage(error) });
      });
    } catch (error) {
      this.emit({ error: errorMessage(error) });
    }
    return () => {
      lifecycle.abort();
      if (support === "legacy") context?.unregisterTool?.(tool.name);
      for (const execution of this.snapshot.executions)
        if (execution.name === tool.name)
          this.active.get(execution.id)?.abort();
      this.tools.delete(tool.name);
      this.emit({ tools: [...this.tools.values()] });
    };
  }
  async run(
    name: string,
    args: Record<string, unknown>,
    source: Execution["source"] = "human",
    signal?: AbortSignal,
  ) {
    const tool = this.tools.get(name);
    if (!tool) throw new Error(`Tool unavailable: ${name}`);
    const invalid = validateArguments(tool.inputSchema, args);
    if (invalid) throw new Error(invalid);
    const id = crypto.randomUUID();
    const controller = new AbortController();
    const abort = () => controller.abort();
    if (signal?.aborted) abort();
    else signal?.addEventListener("abort", abort, { once: true });
    this.active.set(id, controller);
    this.emit({
      executions: [
        {
          id,
          name,
          args,
          source,
          status: "running" as const,
          startedAt: Date.now(),
        },
        ...this.snapshot.executions,
      ].slice(0, 100),
    });
    const update = (patch: Partial<Execution>) =>
      this.emit({
        executions: this.snapshot.executions.map((e) =>
          e.id === id ? { ...e, ...patch, completedAt: Date.now() } : e,
        ),
      });
    try {
      controller.signal.throwIfAborted();
      const result = await tool.execute(args, {
        signal: controller.signal,
        source,
      });
      controller.signal.throwIfAborted();
      update({ status: "success", result });
      return result;
    } catch (error) {
      update({
        status: controller.signal.aborted ? "cancelled" : "error",
        error: errorMessage(error),
      });
      throw error;
    } finally {
      this.active.delete(id);
      signal?.removeEventListener("abort", abort);
    }
  }
  cancel = (id: string) => this.active.get(id)?.abort();
  clearHistory = () =>
    this.emit({
      executions: this.snapshot.executions.filter(
        (e) => e.status === "running",
      ),
    });
}

"use client";
import {
  createContext,
  useContext,
  useEffect,
  useRef,
  useState,
  useSyncExternalStore,
  type ReactNode,
} from "react";
import { WebMCPStore } from "@/lib/webmcp/store";
import type { WebTool } from "@/lib/mcp/types";
const Context = createContext<WebMCPStore | null>(null);
export function WebMCPProvider({ children }: { children: ReactNode }) {
  const [store] = useState(() => new WebMCPStore());
  useEffect(() => store.detect(), [store]);
  return <Context.Provider value={store}>{children}</Context.Provider>;
}
export function useWebMCP() {
  const store = useContext(Context);
  if (!store) throw new Error("Wrap this component in WebMCPProvider.");
  const snapshot = useSyncExternalStore(
    store.subscribe,
    store.getSnapshot,
    store.getSnapshot,
  );
  return {
    ...snapshot,
    run: store.run.bind(store),
    cancel: store.cancel,
    clearHistory: store.clearHistory,
  };
}
export function useWebMCPTool(tool: WebTool, enabled = true) {
  const store = useContext(Context);
  if (!store) throw new Error("Wrap this component in WebMCPProvider.");
  const latest = useRef(tool.execute);
  useEffect(() => {
    latest.current = tool.execute;
  }, [tool.execute]);
  const metadata = JSON.stringify({
    name: tool.name,
    title: tool.title,
    description: tool.description,
    inputSchema: tool.inputSchema,
    annotations: tool.annotations,
  });
  useEffect(() => {
    if (!enabled) return;
    return store.register({
      ...JSON.parse(metadata),
      execute: (args, context) => latest.current(args, context),
    });
  }, [store, metadata, enabled]);
}
